function wPick(pool,used,di){const quick=di<5?pool.filter(r=>r.time_minutes&&r.time_minutes<=90):pool;if(quick.length>=7)pool=quick;const free=pool.filter(r=>!used.has(r.id));const src=free.length?free:pool;if(!src.length)return null;const r=src[Math.floor(Math.random()*src.length)];used.add(r.id);return r.id}
