/* --- timers: hours, ranges, several durations in one step --- */
const NOLET='(?![a-zа-яёәіңғүұқөһ])';
const DUR_RE=new RegExp('(\\d+(?:[.,]\\d+)?)(?:\\s*[–—-]\\s*(\\d+(?:[.,]\\d+)?))?\\s*(минут[а-яәіңғүұқөһ]*|мин\\.?'+NOLET+'|minutes?'+NOLET+'|mins?'+NOLET+'|час(?:а|ов|ам)?'+NOLET+'|ч\\.?'+NOLET+'|сағат[а-яәіңғүұқөһ]*|hours?'+NOLET+'|hrs?'+NOLET+')','gi');
function stepDurations(t){t=String(t);const out=[];let m,prev=null;DUR_RE.lastIndex=0;
 while((m=DUR_RE.exec(t))){const hour=/^(час|ч|сағ|hour|hr)/i.test(m[3]);const v=parseFloat((m[2]||m[1]).replace(',','.'));let mins=Math.round(v*(hour?60:1));
  if(prev&&prev.hour&&!hour&&m.index-prev.end<=3){out[out.length-1]+=mins}else if(mins>0&&mins<=1440)out.push(mins);
  prev={hour,end:m.index+m[0].length}}
 if(/полчаса|жарты сағат|half an hour/i.test(t)&&!out.includes(30))out.push(30);
 return out.slice(0,3)}
stepMinutes=function(t){return stepDurations(t)[0]||0};
function fmtDur(m){return m>=60?Math.floor(m/60)+' '+tr('hShort')+(m%60?' '+(m%60)+' '+tr('min'):''):m+' '+tr('min')}
fmtT=function(s){const h=Math.floor(s/3600),m=Math.floor(s%3600/60);return (h?h+':'+String(m).padStart(2,'0'):m)+':'+String(s%60).padStart(2,'0')};
function saveState(){try{if(view==='cook'&&cook)LS.set('alicook-state',{v:'cook',id:cook.r.id,i:cook.i,serv,di:cook.di||0,end:cook.iv?cook.end:0,t:Date.now()});else if(view==='recipe'&&curId!=null)LS.set('alicook-state',{v:'recipe',id:curId,serv,t:Date.now()});else LS.set('alicook-state',null)}catch(e){}}
function cookTick(){if(!cook)return;cook.left=Math.max(0,Math.round((cook.end-Date.now())/1000));if(cook.left<=0){timerFinished();return}const el=document.getElementById('ck-tm');if(el)el.textContent=fmtT(cook.left)}
function startCookTimer(k,durs){primeAudio();const mins=durs[k];cook.di=k;cook.left=mins*60;cook.end=Date.now()+mins*60000;
 try{if(window.AliCook&&AliCook.startTimerText)AliCook.startTimerText(mins*60,localTitle(cook.r)+' — '+tr('timerNote'));else if(nativeTimer())AliCook.startTimer(mins*60)}catch(e){}
 cook.iv=setInterval(cookTick,500);saveState();renderCook()}
renderCook=function(){let c=document.getElementById('cook');if(!c){c=document.createElement('div');c.id='cook';c.className='cook';document.body.appendChild(c)}
 const t=cook.steps[cook.i],durs=stepDurations(t),last=cook.i===cook.steps.length-1;if(cook.di==null||cook.di>=durs.length)cook.di=0;
 c.innerHTML='<div class="row" style="align-items:center"><div class="ct" style="flex:1">'+esc(localTitle(cook.r))+'<br>'+tr('stepOf')+' '+(cook.i+1)+' '+tr('of2')+' '+cook.steps.length+'</div><button class="ghost" id="ck-x" style="flex:none;min-height:44px">'+tr('exitCook')+'</button></div><div class="cs">'+esc(t)+'</div>'+
 (durs.length?'<div class="tm" id="ck-tm">'+(cook.iv||cook.left?fmtT(cook.left):fmtT(durs[cook.di]*60))+'</div><div class="trow">'+durs.map((m,k)=>'<button class="ghost" data-tk="'+k+'">'+(cook.iv&&cook.di===k?tr('stop'):tr('timer')+' '+fmtDur(m))+'</button>').join('')+'</div>':'')+
 '<div class="row"><button class="ghost" id="ck-prev"'+(cook.i?'':' disabled')+'>'+tr('prev')+'</button><button id="ck-next">'+(last?tr('done'):tr('next'))+'</button></div>';
 document.getElementById('ck-x').onclick=closeCook;
 document.getElementById('ck-prev').onclick=()=>{if(cook.i){stopTimer();cook.left=0;cook.di=0;cook.i--;saveState();renderCook()}};
 document.getElementById('ck-next').onclick=()=>{stopTimer();cook.left=0;cook.di=0;if(last)closeCook();else{cook.i++;saveState();renderCook()}};
 c.querySelectorAll('[data-tk]').forEach(b=>b.onclick=()=>{const k=+b.dataset.tk;if(cook.iv){const same=cook.di===k;stopTimer();cook.left=0;if(same){saveState();renderCook();return}}startCookTimer(k,durs)});
 if(cook.ringing)showAlarmOff()};
timerFinished=function(){if(!cook)return;if(cook.iv){clearInterval(cook.iv);cook.iv=null}cook.left=0;if(!cook.ringing){cook.ringing=true;beep()}saveState();renderCook();const el=document.getElementById('ck-tm');if(el){el.textContent=tr('timerDone');el.classList.add('done')}showAlarmOff()};
window.onNativeTimerDone=function(){if(cook&&view==='cook'){cook.ringing=true;timerFinished()}};
{const _oc=openCook;openCook=function(r,steps){_oc(r,steps);saveState()};const _cc=closeCook;closeCook=function(){_cc();saveState()}}

/* --- appliance hints: a step with several actions gets a hint for each of them --- */
{const _sm=stepModes,_mt=modeText;
 const SPLIT=/;\s*|\.\s+|,\s*(?=затем|потом|после|добавьте|влейте|залейте|всыпьте|положите|накройте|убавьте|уменьшите|переложите)|\s+и\s+(?=вари|туши|томи|жарь|обжар|запек|кипят|готовьте)/i;
 stepModes=function(t){const whole=_sm(t);if(whole.oven)return whole;const parts=String(t).split(SPLIT).map(x=>x&&x.trim()).filter(Boolean);
  if(parts.length>1){const pm=parts.map(_sm).filter(m=>m.stove||m.mc||m.tm);if(pm.length>1)whole.parts=pm}return whole};
 modeText=function(kind,m){if(m&&m.parts&&kind!=='oven'){const tx=[];m.parts.forEach(p=>{const s=_mt(kind,p);if(s&&tx[tx.length-1]!==s)tx.push(s)});if(tx.length>1)return tx.join(' → ')}return _mt(kind,m)}}

