/* --- typo-tolerant search: a word that matches nothing is replaced by the nearest known word --- */
const S_ALL=[...sIndex.values()].join(' ');const S_VOCAB=[...new Set(S_ALL.split(/[^a-zа-яәіңғүұқөһ0-9]+/).filter(w=>w.length>=4))];
function lev(a,b,lim){const n=a.length,m=b.length;if(Math.abs(n-m)>lim)return lim+1;let p2=null,p=[],c;for(let j=0;j<=m;j++)p[j]=j;
 for(let i=1;i<=n;i++){c=[i];let mn=i;for(let j=1;j<=m;j++){let d=Math.min(p[j]+1,c[j-1]+1,p[j-1]+(a[i-1]===b[j-1]?0:1));if(p2&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])d=Math.min(d,p2[j-2]+1);c[j]=d;if(d<mn)mn=d}if(mn>lim)return lim+1;p2=p;p=c}return p[m]}
const fixCache=new Map();const S_FREQ=new Map();S_ALL.split(/[^a-zа-яәіңғүұқөһ0-9]+/).forEach(w=>{if(w.length>=4)S_FREQ.set(w,(S_FREQ.get(w)||0)+1)});
function fixWord(w){const lim=w.length>=7?2:1;let best=null,bd=lim+1,bf=-1;
 /* whole words first; among equally close ones the more common word wins */
 for(const v of S_VOCAB){if(Math.abs(v.length-w.length)>lim||v[0]!==w[0])continue;const d=lev(w,v,lim),f=S_FREQ.get(v)||0;if(d<bd||(d===bd&&d<=lim&&f>bf)){bd=d;best=v;bf=f}}
 if(best&&bd<=lim)return best;
 /* then the beginning of a longer word, for a query that is still being typed */
 if(w.length>=5){for(const v of S_VOCAB){if(v.length<=w.length+lim||v[0]!==w[0])continue;const c=v.slice(0,w.length),d=lev(w,c,1);if(d<=1)return c}}
 return null}
function fixQ(q){const n=norm(q).trim();if(!n)return n;if(fixCache.has(n))return fixCache.get(n);let changed=false;
 const out=n.split(/\s+/).map(w=>{if(w.length<4||S_ALL.includes(w))return w;const f=fixWord(w);if(f){changed=true;return f}return w}).join(' ');
 const res=changed?out:n;if(fixCache.size>300)fixCache.clear();fixCache.set(n,res);return res}
