updFilterBtn=function(){const n=[category,cuisineSel,timeSel,sortSel,dietSel].filter(s=>s.value).length;fltBtn.textContent='☰ '+tr('filters')+(n?' ('+n+')':'');fltBtn.classList.toggle('on',n>0);setBtn.setAttribute('aria-label',tr('settings'))};

/* --- weekly menu picks by dish type --- */
wPool=function(slot){return recipes.filter(r=>{if(!wOk(r))return false;if(slot==='wb')return r.type==='Завтраки'||(r.type==='Гарниры и каши'&&/каша|ботқа/i.test(r.title));if(slot==='wl')return r.type==='Супы';return r.type==='Вторые блюда'})};

/* --- timers: several at once, visible on every screen, started from the recipe or the cooking mode --- */
let timers=(LS.get('alicook-timers',[])||[]).filter(t=>t&&t.id&&t.end);
const tBar=document.createElement('div');tBar.id='tbar';document.body.appendChild(tBar);
function saveTimers(){LS.set('alicook-timers',timers)}
function nativeMulti(){return !!(window.AliCook&&AliCook.startTimerId)}
function fmtLeft(t){return fmtT(Math.max(0,Math.round((t.end-Date.now())/1000)))}
function refreshTimerViews(){renderTimers();if(view==='cook'&&cook)renderCook();else if(view==='recipe')paintStepTimers()}
function addTimer(mins,label,rid,key){primeAudio();let id=1;while(timers.some(t=>t.id===id))id++;if(id>50)return null;
 const t={id,label,rid,key,mins,end:Date.now()+mins*60000,done:false};timers.push(t);saveTimers();
 try{const txt=label+' — '+tr('timerNote');if(nativeMulti())AliCook.startTimerId(id,mins*60,txt);else if(window.AliCook&&AliCook.startTimerText)AliCook.startTimerText(mins*60,txt);else if(nativeTimer())AliCook.startTimer(mins*60)}catch(e){}
 refreshTimerViews();return t}
function removeTimer(id){if(!timers.some(x=>x.id===id))return;timers=timers.filter(x=>x.id!==id);saveTimers();
 try{if(nativeMulti())AliCook.cancelTimerId(id);else if(window.AliCook&&AliCook.cancelTimer)AliCook.cancelTimer()}catch(e){}
 if(!timers.some(x=>x.done))stopBeep();refreshTimerViews()}
function timerDone(t,quiet){if(t.done)return;t.done=true;saveTimers();if(!quiet)beep();refreshTimerViews()}
function renderTimers(){document.documentElement.classList.toggle('has-timers',timers.length>0);
 tBar.innerHTML=timers.map(t=>'<span class="tchip'+(t.done?' done':'')+'" data-t="'+t.id+'"><b>'+(t.done?'🔔 '+tr('timerDone'):'<span data-tl="'+t.id+'">⏱ '+fmtLeft(t)+'</span>')+'</b> <span style="overflow:hidden;text-overflow:ellipsis">'+esc(t.label)+'</span><button data-tx="'+t.id+'" aria-label="×">×</button></span>').join('');
 tBar.querySelectorAll('[data-tx]').forEach(b=>b.onclick=e=>{e.stopPropagation();removeTimer(+b.dataset.tx)});
 tBar.querySelectorAll('.tchip').forEach(c=>c.onclick=()=>{const t=timers.find(x=>x.id===+c.dataset.t);if(!t)return;if(t.done){removeTimer(t.id);return}if(t.rid!=null&&view!=='cook'&&(view!=='recipe'||curId!==t.rid))show(t.rid)})}
function tickTimers(){const now=Date.now();timers.forEach(t=>{if(!t.done&&t.end<=now){/* with the native alarm the phone rings and reports back; fall back if it does not */if(!nativeMulti())timerDone(t);else if(now-t.end>4000)timerDone(t,true)}});
 document.querySelectorAll('[data-tl]').forEach(el=>{const t=timers.find(x=>x.id===+el.dataset.tl);if(t&&!t.done)el.textContent='⏱ '+fmtLeft(t)});
 const big=document.getElementById('ck-tm');if(big&&big.dataset.tm){const t=timers.find(x=>x.id===+big.dataset.tm);if(t&&!t.done)big.textContent=fmtLeft(t)}}
setInterval(tickTimers,500);
window.onNativeTimerDone=function(id){const t=timers.find(x=>x.id===id)||timers.find(x=>!x.done&&x.end<=Date.now()+2000);if(t)timerDone(t,true)};
function paintStepTimers(){try{if(view!=='recipe'||curId==null)return;const r=recipes.find(x=>x.id===curId),ol=app.querySelector('ol');if(!r||!ol)return;const steps=r['steps_'+language]||r.steps;
 [...ol.children].forEach((li,k)=>{li.querySelectorAll('.tsp').forEach(e=>e.remove());const ds=stepDurations(steps[k]||'');if(!ds.length)return;const sp=document.createElement('span');sp.className='tsp';
  ds.forEach((m,k2)=>{const key=r.id+':'+k+':'+k2,t=timers.find(x=>x.key===key),b=document.createElement('button');b.className='tbtn'+(t?(t.done?' done':' on'):'');
   if(t){b.innerHTML=t.done?'🔔 '+tr('alarmOff'):'<span data-tl="'+t.id+'">⏱ '+fmtLeft(t)+'</span> ✕';b.onclick=()=>removeTimer(t.id)}
   else{b.textContent='⏱ '+fmtDur(m);b.onclick=()=>addTimer(m,localTitle(r)+' · '+tr('timerStep')+' '+(k+1),r.id,key)}
   sp.appendChild(b)});li.appendChild(sp)})}catch(e){}}
renderCook=function(){let c=document.getElementById('cook');if(!c){c=document.createElement('div');c.id='cook';c.className='cook';document.body.appendChild(c)}
 const r=cook.r,t=cook.steps[cook.i],durs=stepDurations(t),last=cook.i===cook.steps.length-1;
 const keyOf=k=>r.id+':'+cook.i+':'+k,run=durs.map((m,k)=>timers.find(x=>x.key===keyOf(k))),first=run.find(Boolean);
 c.innerHTML='<div class="row" style="align-items:center"><div class="ct" style="flex:1">'+esc(localTitle(r))+'<br>'+tr('stepOf')+' '+(cook.i+1)+' '+tr('of2')+' '+cook.steps.length+'</div><button class="ghost" id="ck-x" style="flex:none;min-height:44px">'+tr('exitCook')+'</button></div><div class="cs">'+esc(t)+'</div>'+
 (durs.length?'<div class="tm'+(first&&first.done?' done':'')+'" id="ck-tm"'+(first&&!first.done?' data-tm="'+first.id+'"':'')+'>'+(first?(first.done?tr('timerDone'):fmtLeft(first)):fmtT(durs[0]*60))+'</div><div class="trow">'+durs.map((m,k)=>{const x=run[k];return '<button class="ghost" data-tk="'+k+'"'+(x&&x.done?' style="background:#c0392b;color:#fff"':'')+'>'+(x?(x.done?tr('alarmOff'):tr('stop')+' '+fmtDur(m)):tr('timer')+' '+fmtDur(m))+'</button>'}).join('')+'</div>':'')+
 '<div class="row"><button class="ghost" id="ck-prev"'+(cook.i?'':' disabled')+'>'+tr('prev')+'</button><button id="ck-next">'+(last?tr('done'):tr('next'))+'</button></div>';
 document.getElementById('ck-x').onclick=closeCook;
 document.getElementById('ck-prev').onclick=()=>{if(cook.i){cook.i--;saveState();renderCook()}};
 document.getElementById('ck-next').onclick=()=>{if(last)closeCook();else{cook.i++;saveState();renderCook()}};
 c.querySelectorAll('[data-tk]').forEach(b=>b.onclick=()=>{const k=+b.dataset.tk,x=run[k];if(x)removeTimer(x.id);else addTimer(durs[k],localTitle(r)+' · '+tr('timerStep')+' '+(cook.i+1),r.id,keyOf(k))})};
/* leaving the cooking mode no longer stops the timers */
closeCook=function(){bridge(false);const c=document.getElementById('cook');if(c)c.remove();view='recipe';cook=null;saveState();paintStepTimers()};

/* --- protein, fat and carbohydrates per serving next to the calories --- */
function paintPfc(){try{if(view!=='recipe'||curId==null)return;const r=recipes.find(x=>x.id===curId),k=app.querySelector('.kcal');if(!r||!r.pfc||!k||app.querySelector('.pfc'))return;const n=r.servings||1;
 k.insertAdjacentHTML('afterend',' <span class="pfc">· '+tr('prot')+' '+Math.round(r.pfc[0]/n)+' · '+tr('fat')+' '+Math.round(r.pfc[1]/n)+' · '+tr('carb')+' '+Math.round(r.pfc[2]/n)+' '+tr('grams')+'</span>')}catch(e){}}

/* --- backup to a file --- */
function backupText(){const data={};BK_KEYS.forEach(k=>{try{const v=localStorage.getItem(k);if(v!=null)data[k]=v}catch(e){}});return JSON.stringify({app:'alicook',v:1,data})}
window.onBackupSaved=function(ok){const n=document.getElementById('exp-note');if(n)n.textContent=tr(ok?'fileSaved':'fileFail')};
window.onBackupFile=function(text){if(view!=='settings')renderSettings();const n=document.getElementById('imp-note');if(!text){if(n)n.textContent=tr('fileBad');return}document.getElementById('imp-text').value=text;document.getElementById('imp-btn').click()};
{const _rs=renderSettings;renderSettings=function(){_rs();if(!(window.AliCook&&AliCook.exportFile))return;const eb=document.getElementById('exp-btn'),ib=document.getElementById('imp-btn');
 const s=document.createElement('button');s.id='file-save';s.textContent=tr('saveFile');s.onclick=()=>{try{AliCook.exportFile('alicook-backup-'+new Date().toISOString().slice(0,10)+'.json',backupText())}catch(e){}};eb.parentNode.insertBefore(s,eb);
 const l=document.createElement('button');l.id='file-load';l.textContent=tr('loadFile');l.onclick=()=>{try{AliCook.importFile()}catch(e){}};ib.parentNode.insertBefore(l,ib)};setBtn.onclick=()=>renderSettings()}

/* --- glue --- */
{const _show=show;show=function(id){_show(id);paintPfc();paintStepTimers()};
 const _al=applyLanguage;applyLanguage=function(){_al();labelCuisines();renderTimers()};
 const _ab=appBack;appBack=function(){if(view==='list'&&panel.classList.contains('hidden')&&!filterMode&&cuisineSel.value&&!category.value&&!timeSel.value&&!sortSel.value&&!dietSel.value&&!search.value){cuisineSel.value='';render();return true}return _ab()};window.appBack=appBack}
labelCuisines();applyLanguage();
/* timers that ran out while the app was closed are shown as finished */
timers.forEach(t=>{if(!t.done&&t.end<=Date.now())t.done=true});saveTimers();renderTimers();if(view==='recipe')paintStepTimers();if(view==='cook'&&cook)renderCook();
paintPfc();
